style.css:
@-moz-document domain("drive.google.com") {
/* --- FIX: HIDE ORIGINAL LOGOS --- */
/* These selectors aggressively hide ALL default logo versions */
#logo img,
#logo svg,
.gb_sc img,
.gb_sc svg,
#hplogo img,
#hplogo svg,
.lnXdpd, /* Confirmed SVG class from earlier */
.logocont, /* Sometimes used as a container */
.RNNXgb a:first-child img {
    display: none !important;
    visibility: hidden !important;
    width: 0 !important;
    height: 0 !important;
}

    /* 1. Hide the entire area where the logo and search bar live */
    .gb_qc .gb_Cc, /* Older selector for logo container */
    .gb_qc .gb_Dc, /* Newer selector for logo container */
    .gb_qc .gb_Ec { /* Selector for the navigation area around the logo */
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
        /* Ensures the space is not used */
        width: 0 !important;
        height: 0 !important;
    }
    
    /* 2. Inject the custom image into the main top-left search area container */
    .gb_Mc {
        /* Set dimensions for the space */
        width: 40px !important;
        height: 40px !important;
        margin-left: 10px !important;
        
        /* Your custom image link */
        background-image: url("https://i.imgur.com/xAGXiJK.png") !important; 
        
        /* Force the image to be visible */
        visibility: visible !important;
        opacity: 1 !important;
        
        /* Image display settings */
        background-repeat: no-repeat !important;
        background-position: center center !important; 
        background-size: contain !important; 
    }
}
